const config = $('Course & Auth Config').first().json;

// Clean and parse slug from course_input (URL or slug)
let rawSlug = (config.course_input || '1-natural-language-processing').trim();
rawSlug = rawSlug.split('?')[0].replace(/\/+$/, '');
if (rawSlug.includes('/')) {
  const parts = rawSlug.split('/');
  rawSlug = parts[parts.length - 1];
}

let cookieHeader = '';
if (config.session_cookie && config.session_cookie.trim().length > 0) {
  cookieHeader = config.session_cookie.trim();
} else {
  const loginResponse = $input.first();
  const headers = loginResponse.json.headers || {};
  const setCookie = headers['set-cookie'] || [];
  if (Array.isArray(setCookie)) {
    cookieHeader = setCookie.map(c => c.split(';')[0]).join('; ');
  } else if (typeof setCookie === 'string') {
    cookieHeader = setCookie.split(';')[0];
  }
}

return [{
  json: {
    course_slug: rawSlug,
    cookie: cookieHeader
  }
}];

const apiRes = $input.first().json;
const authInfo = $('Extract Auth Cookie & Slug').first().json;

// Support both apiRes.data.course and apiRes.data and apiRes
const root = apiRes.data?.course || apiRes.data || apiRes.course || apiRes;

// VTU uses 'lessons' for modules, and inside each lesson is 'lectures'
const modules = root.lessons || root.curriculum || root.modules || root.sections || [];
const lectureQueue = [];

if (Array.isArray(modules)) {
  modules.forEach((mod, modIdx) => {
    const modTitle = mod.name || mod.title || `Module ${modIdx + 1}`;
    const items = mod.lectures || mod.lessons || mod.items || [];

    if (Array.isArray(items)) {
      items.forEach((item, itemIdx) => {
        const rawProgress = item.progressPercent ?? item.progress_percent ?? item.progress ?? 0;
        const isDone = !!(item.is_completed ?? item.isCompleted ?? item.completed ?? (Number(rawProgress) >= 90));

        lectureQueue.push({
          lecture_id: item.id || item.lecture_id,
          title: item.name || item.title || `Lecture ${itemIdx + 1}`,
          duration: Math.max(60, Number(item.duration_seconds || item.duration) || 300),
          module_title: modTitle,
          is_completed: isDone,
          course_slug: authInfo.course_slug,
          cookie: authInfo.cookie
        });
      });
    }
  });
}

// Direct lectures fallback
if (lectureQueue.length === 0 && Array.isArray(root.lectures)) {
  root.lectures.forEach((item, itemIdx) => {
    const rawProgress = item.progressPercent ?? item.progress_percent ?? 0;
    const isDone = !!(item.is_completed ?? (Number(rawProgress) >= 90));
    lectureQueue.push({
      lecture_id: item.id,
      title: item.name || item.title || `Lecture ${itemIdx + 1}`,
      duration: Math.max(60, Number(item.duration) || 300),
      module_title: 'Course Curriculum',
      is_completed: isDone,
      course_slug: authInfo.course_slug,
      cookie: authInfo.cookie
    });
  });
}

// Filter pending
const pending = lectureQueue.filter(l => !l.is_completed);

if (pending.length === 0) {
  return [{
    json: {
      all_completed: true,
      message: 'All lectures in this course are already 100% completed!',
      total_lectures: lectureQueue.length,
      course_slug: authInfo.course_slug
    }
  }];
}

return pending.map(item => ({ json: item }));

const res = $input.first().json;
const item = $('Loop Over Lectures').first().json;

return [{
  json: {
    lecture_id: item.lecture_id,
    title: item.title,
    module: item.module_title,
    duration_seconds: item.duration,
    success: res.success || false,
    is_completed: res.data ? res.data.is_completed : true,
    percent: res.data ? res.data.percent : 100
  }
}];

const allItems = $input.all();
const config = $('Extract Auth Cookie & Slug').first().json;

const totalProcessed = allItems.length;
const completedCount = allItems.filter(i => i.json.is_completed || i.json.success).length;

return [{
  json: {
    status: 'COMPLETED',
    course_slug: config.course_slug,
    lectures_completed: completedCount,
    total_processed: totalProcessed,
    completion_percent: 100,
    message: `🎉 Finished! Completed ${completedCount}/${totalProcessed} lectures for course: ${config.course_slug}`,
    timestamp: new Date().toISOString()
  }
}];
